//! Detached optgroup metadata copies reflection retains actual DOMString attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><select id=select><optgroup id=optgroup label=Group><option id=option value=one>One</option></optgroup><option value=two>Two</option></select><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://optgroup-label.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn optgroup_detached_copy_native_shallow_clone_keeps_exact_independent_attributes(){let(mut d,mut f,mut p)=fixture();let controls=f.controls.len();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('optgroup');x.label='A\ud800Z';x.disabled=true;var old=x.getAttributeNode('label'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var copy=x.cloneNode(false);if(copy===x||!(copy instanceof HTMLOptGroupElement)||copy.ownerDocument!==document||copy.parentNode!==null||copy.firstChild!==null||copy.label!==x.label||!copy.disabled||copy.getAttributeNode('label')===old)throw 'actual shallow group clone';copy.label='independent';copy.disabled=false;if(x.label!=='A\ud800Z'||!x.disabled||old.value!==x.label||watch.takeRecords().length||x.firstChild.textContent!=='One')throw 'independent group copy';"#);assert_eq!(f.controls.len(),controls);}
#[test]
fn optgroup_detached_copy_inert_to_native_shallow_import_keeps_real_owner(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','optgroup');x.label='A\udfffZ';x.disabled=true;var copy=document.importNode(x,false);if(!(copy instanceof HTMLOptGroupElement)||copy.ownerDocument!==document||copy.parentNode!==null||copy.firstChild!==null||copy.label!==x.label||!copy.disabled||copy.getAttributeNode('label')===x.getAttributeNode('label'))throw 'real imported group';copy.label='independent';if(x.label!=='A\udfffZ'||x.ownerDocument!==owner)throw 'import isolation';"#);}
#[test]
fn optgroup_detached_copy_into_inert_document_keeps_exact_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('optgroup'),owner=new Document();x.label='A\ud800Z';x.disabled=true;var copy=owner.importNode(x,false);if(!(copy instanceof HTMLOptGroupElement)||copy.ownerDocument!==owner||copy.parentNode!==null||copy.firstChild!==null||copy.label!==x.label||!copy.disabled||copy.getAttributeNode('label')===x.getAttributeNode('label'))throw 'inert imported group';copy.label='independent';if(x.label!=='A\ud800Z'||x.firstChild.textContent!=='One')throw 'inert import isolation';"#);}

#[test]
fn optgroup_detached_copy_resource_refusals_publish_nothing_and_recover(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var source=new Document().createElementNS('http://www.w3.org/1999/xhtml','optgroup');source.label='retained';source.disabled=true;"}else{"var source=document.getElementById('optgroup');source.label='retained';source.disabled=true;"});run(&mut d,&mut f,&mut p,"var attr=source.getAttributeNode('label'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,childList:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let retained=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};let code=if inert{"var copy=document.importNode(source,false);"}else{"var copy=source.cloneNode(false);"};let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound")||e.contains("time"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.state.retained_limit=retained;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.label!=='retained'||source.getAttributeNode('label')!==attr||attr.ownerElement!==source||watch.takeRecords().length||document.getElementById('neighbor').value!=='seed')throw 'atomic copy refusal';");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"if(!(copy instanceof HTMLOptGroupElement)||copy.parentNode!==null||copy.ownerDocument!==document||copy.label!=='retained'||copy.disabled!==true||copy.getAttributeNode('label')===attr||watch.takeRecords().length)throw 'fresh detached copy recovery';");assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());let(a,b,c)=p.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());}}
}



#[test]
fn optgroup_detached_copy_saved_child_method_checks_origin_before_copy_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('optgroup'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var method=frame.contentWindow.Node.prototype.cloneNode,copy=method.call(source,false);if(!(copy instanceof HTMLOptGroupElement)||copy.parentNode!==null)throw 'same origin native copy';");p.set_location(&crate::navigation::address("https://other-copy.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());p.begin_job();let e=p.runtime.execute("method.call(source,false);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),state);p.set_location(&crate::navigation::address("https://optgroup-label.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"copy=method.call(source,false);if(copy.label!=='Group'||copy.ownerDocument!==document||copy.parentNode!==null)throw 'fresh copy origin recovery';");}



#[test]
fn optgroup_detached_copy_copies_nonce_unsafety_without_fabricating_source_mutation(){let(mut d,mut f,mut p)=fixture();let original=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("optgroup")).unwrap();d.nonce_unsafe_nodes.insert(original);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes[original]);let Value::Host(copy)=p.runtime.execute("document.getElementById('optgroup').cloneNode(false);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("genuine copied node")};let copied=node_index(copy).unwrap();assert_ne!(copied,original);assert!(d.nonce_unsafe_nodes.contains(&copied));assert!(d.nonce_unsafe_nodes.contains(&original));assert_eq!(format!("{:?}",d.nodes[original]),before);assert!(p.state.detached_nodes.contains(&copied));assert!(!p.has_navigation_request());}



#[test]
fn optgroup_detached_copy_empty_deep_boolean_argument_and_saved_method(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','optgroup');source.label='empty';source.disabled=true;var imported=document.importNode(source,true),method=Node.prototype.cloneNode,calls=0,copy=method.call(imported,{valueOf:function(){calls++;throw 'conversion';},toString:function(){calls++;throw 'conversion';}});if(calls||copy===imported||copy.parentNode!==null||copy.firstChild!==null||copy.ownerDocument!==document||copy.label!=='empty'||!copy.disabled||copy.getAttributeNode('label')===imported.getAttributeNode('label'))throw 'empty deep boolean group copy';"#);}
#[test]
fn optgroup_detached_copy_option_descendant_and_active_handler_refusals_keep_sources(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('optgroup'),owner=new Document();");for code in ["source.cloneNode(true);"]{let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("SELECT context")||e.contains("cloning/lifecycle hooks")||e.contains("Cloning this element or its native state is not implemented."),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),state);}
 let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());p.begin_job();run(&mut d,&mut f,&mut p,"var refused=false;try{owner.importNode(source,true);}catch(e){refused=e.name==='NotSupportedError';}if(!refused)throw 'OPTION import lifecycle refusal';");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),state);
 let group=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("optgroup")).unwrap();if let NodeKind::Element{attrs,..}=&mut d.nodes[group].kind{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());p.begin_job();let e=p.runtime.execute("source.cloneNode(false);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("Cloning this element or its native state is not implemented."),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),state);}

#[test]
fn optgroup_detached_copy_passive_deep_topology_is_independent_across_real_owners(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','optgroup');source.label='deep';source.disabled=true;source.appendChild(owner.createTextNode('text'));source.appendChild(owner.createComment('marker'));var imported=document.importNode(source,true),copy=imported.cloneNode(true),other=new Document(),inert=other.importNode(imported,true);for(var node of [imported,copy,inert]){if(node.parentNode!==null||node.label!=='deep'||!node.disabled||node.childNodes.length!==2||node.firstChild.data!=='text'||node.lastChild.data!=='marker'||node.firstChild.parentNode!==node||node.firstChild.ownerDocument!==node.ownerDocument)throw 'independent passive topology';}if(copy.ownerDocument!==document||imported.ownerDocument!==document||inert.ownerDocument!==other||copy.firstChild===imported.firstChild||copy.firstChild===source.firstChild||source.ownerDocument!==owner)throw 'real deep owner identity';copy.label='copy';if(imported.label!=='deep'||source.label!=='deep'||inert.label!=='deep'||imported.firstChild.data!=='text'||source.firstChild.data!=='text'||inert.firstChild.data!=='text')throw 'deep copy isolation';"#);}

#[test]
fn optgroup_detached_copy_select_owned_child_text_write_retains_its_guard(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','optgroup');source.label='passive';source.appendChild(owner.createTextNode('text'));var copy=document.importNode(source,true),inside=document.getElementById('optgroup').firstChild.firstChild;");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.begin_job();let e=p.runtime.execute("inside.data='guarded';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("Changing native control contents or inert resource subtrees is not implemented."),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.begin_job();run(&mut d,&mut f,&mut p,"copy.label='recovered';if(copy.firstChild.data!=='text'||copy.label!=='recovered'||source.label!=='passive')throw 'copy metadata recovery preserves text guard';");}
